        "dua_la_hawla_kanz" to DuaText("אוצר של יאנה", "אין כוח ואין כוח אלא עם אללה.", "לעתים קרובות, בכל עת.", "זה אחד מאוצרות גן העדן."),
        "dua_four_beloved_words" to DuaText("ארבע המילים האהובות ביותר", "תהילה לאללה, כל השבחים הם לאללה, אין ראוי לסגוד אלא לאללה, ואללה הוא הגדול ביותר.", "המילים האהובות ביותר על אללה.", "הם יקרים יותר לנביא ﷺ מכל מה שהשמש זורחת עליו."),
        "dua_two_light_words" to DuaText("שתי מילים אור על הלשון", "תהילה לאללה וכל השבח הוא שלו; תהילה לאללה המפואר.", "קל על הלשון, כבד על הסקאלה.", "אהוב על הרחמן, קל על הלשון וכבד בסולם. (החדית' האחרון של אל-בוכרי)"),
        "dua_ya_dhal_jalal" to DuaText("יא דהל-ג'לאלי ואל-איכרם", "הו בעל הוד וכבוד!", "החזיקו בזה בדואה - הוראת הנביא ﷺ.", "הנביא ﷺ אמר: אחזו ב'יא דהל-ג'לאלי ואל-איכרם'."),
