        "dua_sleep_khalaqta_nafsi" to DuaText("אתה יצרת את הנשמה שלי", "הו אללה, אתה יצרת את נשמתי ואתה תיקח אותה. מותו וחייו שייכים לך. אם אתה משאיר אותו בחיים, הגן עליו, ואם אתה גורם לו למות, סלח לו. הו אללה, אני מבקש ממך רווחה.", "לפני השינה - מסופר על ידי אבן עומר (RA).", "הנביא ﷺ הורה לומר זאת לפני השינה."),
        "dua_sleep_atamana" to DuaText("הכרת תודה לפני השינה", "כל השבחים הם לאללה שהאכיל אותנו, נתן לנו לשתות, הספיק לנו ונתן לנו מחסה. כמה יש שאין מי שיספיק להם או ייתן להם מחסה.", "כשהולכים לישון.", "הנביא ﷺ אמר את זה כשהלך לישון."),
        "dua_sleep_rabbas_samawat" to DuaText("אדון השמים - שלם את חובנו", "הו אללה, אדון השמים, הארץ והכס האדיר, אדוננו ואדון כל הדברים, מפצל הזרע ואבן התמר, מגלה התורה, האינג'יל והפורקן! אני מחפש בך מקלט מהרע של כל מה שאת מחזיקה בעורפו. הו אללה, אתה הראשון, אין דבר לפניך; אתה האחרון, אין דבר אחריך; אתה המניפסט, אין שום דבר מעליך; אתה הנסתר, אין שום דבר נסתר ממך. הסדר לנו את חובנו ושחרר אותנו מעוני.", "לפני השינה, שכיבה על צד ימין - לימדו לפטימה (RA).", "דואה להקלה מחובות ומצוקה."),
        "dua_sleep_fear" to DuaText("פחד או אי נוחות בשינה", "אני מחפש מקלט בדברים המושלמים של אללה מכעסו ועונשו, מרוע עבדיו ומלחישות השדים ומבואם אלי.", "כאשר מרגישים פחד או אי נוחות בשינה.", "אם תעשה זאת, הדבר הזה לא יזיק לו."),
